effect.shader:
void main(){
vec2 uv=acScreenNorm,p=uv-0.5;
float cx=cos(tiltX),sx=sin(tiltX),cy=cos(tiltY),sy=sin(tiltY);
float den=max(0.18,1.0+(p.x*sy-p.y*sx)*perspective);
vec2 q=vec2(p.x/max(abs(cy),0.08),p.y/max(abs(cx),0.08))/(den*max(zoom,0.05))+0.5;
float valid=step(0.0,q.x)*step(q.x,1.0)*step(0.0,q.y)*step(q.y,1.0);
vec4 src=texture2DCv(inputImg.texture,uv);
vec4 dst=texture2DCv(inputImg.texture,clamp(q,0.0,1.0));
float face=clamp(abs(cx*cy),0.0,1.0);
float directional=clamp(0.72+0.28*(p.x*sy-p.y*sx)+0.25*face,0.25,1.25);
dst.rgb*=mix(1.0,directional,lighting);
gl_FragColor=mix(src,dst,mixAmount*valid);
}
